// Appearance is separate from platform collision and the validated access graph.
import {drawOriginalRegion} from './source-clips.mjs';
export function platformVariant(p){if(p.role==='high')return 0;const n=Number(String(p.id).match(/\d+$/)?.[0]??p.shape??0);return Math.abs(n)%2;}
export function platformClearance(w,p){let support=w.floor;for(const q of w.platforms){if(q===p||!q.active||q.y<=p.y+1)continue;if(q.x<p.x+p.w+12&&q.x+q.w>p.x-12)support=Math.min(support,q.y);}return Math.max(0,support-p.y-24);}
export function platformSurfaceGeometry(frame,p,clearance=Infinity){const r=frame.rect,b=frame.spriteRect||r,span=frame.standingX||[0,1],left=span[0]*r[2],scale=p.w/Math.max(1,(span[1]-span[0])*r[2]),surface=r[1]+(frame.topNormalized??.3)*r[3],split=Math.max(b[1],Math.min(b[1]+b[3],surface+8/scale)),x=(b[0]-r[0]-left)*scale,y=(b[1]-surface)*scale,width=b[2]*scale,upperHeight=(split-b[1])*scale,lowerY=y+upperHeight,lowerHeight=Math.max(0,Math.min((b[1]+b[3]-split)*scale,(p.role==='high'?180:110)-lowerY,clearance-lowerY));return {source:b,x,y,width,height:upperHeight+lowerHeight,clipBottom:lowerY+lowerHeight,upperSource:[b[0],b[1],b[2],split-b[1]],upperHeight,lowerSource:[b[0],split,b[2],b[1]+b[3]-split],lowerY,lowerHeight};}
export function drawCampaignPlatform(c,img,meta,p,clearance){const frame=meta?.frames?.[platformVariant(p)];if(!img||!frame)return false;const g=platformSurfaceGeometry(frame,p,clearance);c.save();c.translate(p.x,p.y);c.beginPath();c.rect(g.x-1,Math.min(-1,g.y-1),g.width+2,Math.max(0,g.clipBottom-Math.min(-1,g.y-1)));c.clip();if(g.upperHeight>0)drawOriginalRegion(c,img,frame,g.upperSource,g.x,g.y,g.width,g.upperHeight);if(g.lowerHeight>0)drawOriginalRegion(c,img,frame,g.lowerSource,g.x,g.lowerY,g.width,g.lowerHeight);c.restore();return true;}
